"170 :     private double solve(double x0, double y0,
171 :                          double x1, double y1,
172 :                          double x2, double y2)
173 :     throws MaxIterationsExceededException, FunctionEvaluationException {
174 : 
175 :         double delta = x1 - x0;
176 :         double oldDelta = delta;
177 : 
178 :         int i = 0;
179 :         while (i < maximalIterationCount) {
180 :             if (Math.abs(y2) < Math.abs(y1)) {
181 :                 // use the bracket point if is better than last approximation
182 :                 x0 = x1;
183 :                 x1 = x2;
184 :                 x2 = x0;
185 :                 y0 = y1;
186 :                 y1 = y2;
187 :                 y2 = y0;
188 :             }
189 :             if (Math.abs(y1) <= functionValueAccuracy) {
190 :                 // Avoid division by very small values. Assume
191 :                 // the iteration has converged (the problem may
192 :                 // still be ill conditioned)
193 :                 setResult(x1, i);
194 :                 return result;
195 :             }
196 :             double dx = (x2 - x1);
197 :             double tolerance =
198 :                 Math.max(relativeAccuracy * Math.abs(x1), absoluteAccuracy);
199 :             if (Math.abs(dx) <= tolerance) {
200 :                 setResult(x1, i);
201 :                 return result;
202 :             }
203 :             if ((Math.abs(oldDelta) < tolerance) ||
204 :                     (Math.abs(y0) <= Math.abs(y1))) {
205 :                 // Force bisection.
206 :                 delta = 0.5 * dx;
207 :                 oldDelta = delta;
208 :             } else {
209 :                 double r3 = y1 / y0;
210 :                 double p;
211 :                 double p1;
212 :                 // the equality test (x0 == x2) is intentional,
213 :                 // it is part of the original Brent's method,
214 :                 // it should NOT be replaced by proximity test
215 :                 if (x0 == x2) {
216 :                     // Linear interpolation.
217 :                     p = dx * r3;
218 :                     p1 = 1.0 - r3;
219 :                 } else {
220 :                     // Inverse quadratic interpolation.
221 :                     double r1 = y0 / y2;
222 :                     double r2 = y1 / y2;
223 :                     p = r3 * (dx * r1 * (r1 - r2) - (x1 - x0) * (r2 - 1.0));
224 :                     p1 = (r1 - 1.0) * (r2 - 1.0) * (r3 - 1.0);
225 :                 }
226 :                 if (p > 0.0) {
227 :                     p1 = -p1;
228 :                 } else {
229 :                     p = -p;
230 :                 }
231 :                 if (2.0 * p >= 1.5 * dx * p1 - Math.abs(tolerance * p1) ||
232 :                         p >= Math.abs(0.5 * oldDelta * p1)) {
233 :                     // Inverse quadratic interpolation gives a value
234 :                     // in the wrong direction, or progress is slow.
235 :                     // Fall back to bisection.
236 :                     delta = 0.5 * dx;
237 :                     oldDelta = delta;
238 :                 } else {
239 :                     oldDelta = delta;
240 :                     delta = p / p1;
241 :                 }
242 :             }
243 :             // Save old X1, Y1 
244 :             x0 = x1;
245 :             y0 = y1;
246 :             // Compute new X1, Y1
247 :             if (Math.abs(delta) > tolerance) {
248 :                 x1 = x1 + delta;
249 :             } else if (dx > 0.0) {
250 :                 x1 = x1 + 0.5 * tolerance;
251 :             } else if (dx <= 0.0) {
252 :                 x1 = x1 - 0.5 * tolerance;
253 :             }
